// Format the error payload for structured logging.
// The Error Trigger node provides:
//   $json.error.message       — error message string
//   $json.error.name          — error type (e.g. Error, TypeError)
//   $json.workflow.id         — failing workflow ID
//   $json.workflow.name       — failing workflow name
//   $json.execution.id        — execution ID
//   $json.lastNodeExecuted    — name of the node that failed
//   $json.timestamp           — when the error occurred

return items.map(item => {
  const err = item.json.error || {};
  const wf = item.json.workflow || {};
  return {
    json: {
      error_message: String(err.message || 'Unknown error').slice(0, 500),
      error_type: err.name || 'Error',
      workflow_id: wf.id || 'unknown',
      workflow_name: wf.name || 'unknown',
      execution_id: item.json.execution?.id || 'unknown',
      last_node: item.json.lastNodeExecuted || 'unknown',
      error_timestamp: item.json.timestamp || new Date().toISOString(),
      severity: 'error',
      raw_preview: JSON.stringify(item.json).slice(0, 1000)
    }
  };
});
